def close(self) -> None:
    """Invoke all close callbacks registered with
    :meth:`call_on_close`, and exit all context managers entered
    with :meth:`with_resource`.

    If a ``cleanup_timeout`` was set, the cleanup operations are
    wrapped in a timeout that forcibly terminates them if they do
    not complete within the specified number of seconds.
    """
    timeout = self.cleanup_timeout

    if timeout is None:
        self._exit_stack.close()
    else:
        self._close_with_timeout(timeout)

    # In case the context is reused, create a new exit stack.
    self._exit_stack = ExitStack()

def _close_with_timeout(self, timeout: float) -> None:
    if hasattr(signal, "SIGALRM"):
        _logger.debug(
            "Running cleanup for context %r with timeout of %.3f seconds.",
            self.info_name,
            timeout,
        )
        previous_handler = signal.signal(
            signal.SIGALRM, self._cleanup_timeout_handler
        )
        signal.setitimer(signal.ITIMER_REAL, timeout)
        try:
            self._exit_stack.close()
        except TimeoutError:
            _logger.warning(
                "Cleanup for context %r timed out after %.3f seconds and "
                "was forcibly terminated.",
                self.info_name,
                timeout,
            )
        finally:
            signal.setitimer(signal.ITIMER_REAL, 0)
            signal.signal(signal.SIGALRM, previous_handler)
    else:
        self._exit_stack.close()

@staticmethod
def _cleanup_timeout_handler(signum: int, frame: t.Any) -> None:
    raise TimeoutError("Context cleanup timed out.")

